import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { Circle } from "@remotion/shapes";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SplitCirclesProps = Record<string, any>;

const SplitCircles: React.FC<SplitCirclesProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  colors = [
    "#FF7E79", // Salmon
    "#FFB480", // Peach
    "#FFE498", // Cream
    "#D4F298", // Lime
    "#98E6C8", // Mint
    "#98B4E6", // Periwinkle
  ],
  radius = 125,
  spacing = 280,
  staggerFrames = 3,
  bounciness = 1.5,
  headerText = "Brand colors",
  headerColor = "#2b2b2b",
}) => {
  useFontLoader(["Inter", "Poppins"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Header Animation
  const headerOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const headerTranslateY = interpolate(frame, [0, 20], [-20, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // Ease out
  });

  // Calculate total width of the spread to center the group
  // The center of the group is the average position of the circles
  // We want the group centered at (width/2, height/2)
  const totalCount = colors.length;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, alignItems: "center", justifyContent: "center" }}>
      {/* Header */}
      <div
        style={{
          position: "absolute",
          top: "15%",
          width: "100%",
          textAlign: "center",
          fontFamily: "Poppins, sans-serif",
          fontWeight: 700,
          fontSize: 60,
          color: headerColor,
          opacity: headerOpacity,
          transform: `translateY(${headerTranslateY}px)`,
          zIndex: 100,
        }}
      >
        {headerText}
      </div>

      <div style={{ position: "relative", width: 0, height: 0 }}>
        {colors.map((color, i) => {
          // Calculate delay for each circle
          const delay = i * staggerFrames;

          // Spring animation for the split movement
          const progress = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 100 + (bounciness * 10), // Adjust stiffness based on bounciness input
            },
          });

          // Calculate target X position relative to center
          // Formula: (i - (N - 1) / 2) * spacing
          // Example for 6 items: indices 0..5. Center is 2.5. 
          // Offsets: -2.5, -1.5, -0.5, 0.5, 1.5, 2.5
          const centerOffset = (totalCount - 1) / 2;
          const targetX = (i - centerOffset) * spacing;
          
          // Interpolate current X from 0 to targetX
          const currentX = interpolate(progress, [0, 1], [0, targetX]);
          
          // Add a slight scale-in effect at the very beginning
          const scale = interpolate(
             frame - (i * 2), // Start slightly faster than the move
             [0, 10], 
             [0, 1], 
             { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                transform: `translate(calc(-50% + ${currentX}px), -50%) scale(${scale})`,
                zIndex: i, // Ensure correct stacking order (last on top)
              }}
            >
              <Circle
                radius={radius}
                fill={color}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SplitCircles;